\title{Vanishing Cyclically Covering Codimension is Equivalent to the
Full-Weight Property of Cyclic Codes}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
Let $q$ be a prime power and $n$ a positive integer, and consider the space
$V = \FF_q^n$ of $q$-ary words of length $n$, indexed by the cyclic group $\Zn$.
A subspace $U \subseteq V$ is \emph{cyclically covering} if every word of $V$ can
be rotated into $U$; the invariant $h_q(n)$ is the maximum codimension attained
by such a subspace. Separately, a \emph{cyclic code} is a rotation-invariant
subspace of $V$, and a codeword has \emph{full Hamming weight} if all of its
coordinates are nonzero. We prove that these two notions meet in a single exact
equivalence:
\[
h_q(n) = 0 \iff \text{every nonzero cyclic code in } \FF_q^n
\text{ contains a full-weight codeword}.
\]
The proof proceeds through a correlation (Fourier-type) transform $\Phi_a$ whose
image is always a cyclic code and whose associated orthogonal hyperplane is
cyclically covering precisely when that image omits every full-weight word. A
coordinate-reversal device converts an arbitrary prescribed cyclic code into the
image of such a transform, closing the equivalence. The argument requires only
that the scalar ring be a field; finiteness of $\FF_q$ is not used, so the
theorem holds verbatim over any field $K$.
\end{abstract}

\section{Introduction}

Two extremal questions, drawn from combinatorial geometry and from algebraic
coding theory, turn out to be one and the same.

\paragraph{Covering side.} Fix the linear cyclic shift on $V = \FF_q^n$. A
subspace $U$ is \emph{cyclically covering} when the shifts of $U$ exhaust $V$:
every $x \in V$ has some shift landing in $U$. The whole space is covering; the
substantive question is how thin a covering subspace can be. Writing the thinness
of a subspace as its codimension $\codim U = n - \dim U$, one sets
\[
h_q(n) = \max\{\codim U : U \subseteq V \text{ cyclically covering}\}.
\]
The extreme case $h_q(n) = 0$ says the only cyclically covering subspace is $V$
itself: covering is maximally rigid.

\paragraph{Coding side.} A \emph{cyclic code} $C \subseteq V$ is a subspace
invariant under the shift---equivalently, an ideal of the quotient ring
$\FF_q[x]/(x^n-1)$. A codeword $c$ has \emph{full Hamming weight} when $c_i \neq
0$ for all $i$. We say $\FF_q^n$ has the \emph{full-weight property} if every
nonzero cyclic code contains at least one full-weight codeword.

\begin{theorem}[Main Theorem]\label{thm:main-intro}
$h_q(n) = 0$ if and only if $\FF_q^n$ has the full-weight property.
\end{theorem}

The mechanism is a correlation transform reminiscent of the discrete Fourier
transform, and the proof is elementary linear algebra once the transform's two
key properties are isolated. We work throughout over an arbitrary field $K$ in
place of $\FF_q$; the classical statement is the case $K = \FF_q$.

\section{Setup and definitions}

Throughout, $n \geq 1$, $K$ is a field, and $V = K^{\Zn}$ is the space of
functions $x : \Zn \to K$, i.e.\ words of length $n$ indexed cyclically. We write
$x_i$ for $x(i)$.

\begin{definition}[Cyclic shift]
For $k \in \Zn$, the shift $\rot_k : V \to V$ is the linear map
$(\rot_k\, x)_i = x_{i+k}$. It satisfies $\rot_k \circ \rot_\ell = \rot_{k+\ell}$
and $\rot_0 = \mathrm{id}$.
\end{definition}

\begin{definition}[Reversal]
The reversal $\rev : V \to V$ is the linear involution $(\rev\, x)_i = x_{-i}$; it
is nonzero on nonzero inputs.
\end{definition}

\begin{definition}[Pairing and functionals]
The standard bilinear pairing is $\ip{a}{x} = \sum_{i \in \Zn} a_i\, x_i$. For
fixed $a$ this defines a functional $\mathrm{pair}(a) : V \to K$. Conversely, to
any functional $f : V \to K$ we associate its coefficient vector $\coeff(f) \in V$
by $\coeff(f)_i = f(e_i)$, where $e_i$ is the standard basis word with a single
$1$ in position $i$.
\end{definition}

\begin{definition}[Full weight]
A word $c \in V$ has \emph{full Hamming weight}, written $\FullWeight(c)$, if
$c_i \neq 0$ for every $i$.
\end{definition}

\begin{definition}[Cyclic code]
A subspace $C \subseteq V$ is a \emph{cyclic code} if $\rot_1(C) \subseteq C$;
equivalently (Lemma~\ref{lem:shiftinv}) $\rot_k(C) \subseteq C$ for all $k$.
\end{definition}

\begin{definition}[Cyclically covering subspace]
A subspace $U \subseteq V$ is \emph{cyclically covering} if for every $x \in V$
there exists $k \in \Zn$ with $\rot_k(x) \in U$.
\end{definition}

\begin{definition}[The invariants]
We say $h_q(n) = 0$ holds if the only cyclically covering subspace of $V$ is $V$
itself. We say $\FF_q^n$ has the \emph{full-weight property} if every cyclic code
$C \neq \{0\}$ contains a full-weight codeword.
\end{definition}

The identification of ``$h_q(n)=0$'' with the vanishing of the maximum covering
codimension is justified because that maximum is $0$ exactly when no proper
covering subspace exists, i.e.\ when every covering subspace is all of $V$.

\section{Preliminaries on the shift}

\begin{lemma}[Shift-invariance of cyclic codes]\label{lem:shiftinv}
If $C$ is a cyclic code and $x \in C$, then $\rot_k(x) \in C$ for every $k \in
\Zn$.
\end{lemma}
\begin{proof}
By induction on $m \in \NN$ one shows $\rot_m(x) \in C$, using $\rot_0 =
\mathrm{id}$ and $\rot_{m+1}(x) = \rot_1(\rot_m(x)) \in C$. Every $k \in \Zn$ is
the image of its natural representative, so $\rot_k(x) \in C$.
\end{proof}

\begin{lemma}[Monotonicity of covering]\label{lem:mono}
If $U \subseteq W$ and $U$ is cyclically covering, then so is $W$.
\end{lemma}
\begin{proof}
A shift of $x$ landing in $U$ also lands in $W \supseteq U$.
\end{proof}

\begin{lemma}[Recovering functionals]\label{lem:coeff}
For any functional $f : V \to K$ we have $\mathrm{pair}(\coeff(f)) = f$.
Consequently $\coeff(f) \neq 0$ when $f \neq 0$, and $\mathrm{pair}(a) \neq 0$
when $a \neq 0$.
\end{lemma}
\begin{proof}
Write $x = \sum_i x_i\, e_i$; linearity gives $f(x) = \sum_i x_i f(e_i) =
\ip{\coeff(f)}{x}$. If $\coeff(f)=0$ then $f = \mathrm{pair}(0)=0$; and
$\mathrm{pair}(a)(e_j)=a_j$, so $\mathrm{pair}(a)=0$ forces $a=0$.
\end{proof}

\begin{lemma}[Separation by a functional]\label{lem:sep}
If $U \subsetneq V$ is proper, there is a nonzero functional $f : V \to K$
vanishing on $U$.
\end{lemma}
\begin{proof}
$V/U$ is nontrivial, hence carries a nonzero functional $g$; the composite $f = g
\circ \pi$ with the projection $\pi : V \to V/U$ is nonzero and vanishes on $U$.
\end{proof}

\section{The correlation transform and the core bridge}

\begin{definition}[Correlation transform]
For $a \in V$ define $\Phi_a : V \to V$ by
\[
\Phi_a(x)_k = \ip{a}{\rot_k(x)} = \sum_i a_i\, x_{i+k}.
\]
\end{definition}

\begin{lemma}[Equivariance]\label{lem:equiv}
$\Phi_a(\rot_1 x) = \rot_1(\Phi_a(x))$.
\end{lemma}
\begin{proof}
$\Phi_a(\rot_1 x)_k = \ip{a}{\rot_{k+1} x} = \Phi_a(x)_{k+1} =
(\rot_1 \Phi_a(x))_k$.
\end{proof}

\begin{proposition}[Image is a cyclic code]\label{prop:image}
For every $a \in V$, the image $\Phi_a(V)$ is a cyclic code.
\end{proposition}
\begin{proof}
The image is a subspace; closure under $\rot_1$ follows from
Lemma~\ref{lem:equiv}: if $w = \Phi_a(y)$ then $\rot_1 w = \Phi_a(\rot_1 y) \in
\Phi_a(V)$.
\end{proof}

\begin{proposition}[Nontriviality]\label{prop:nontriv}
If $a \neq 0$ then $\Phi_a(V) \neq \{0\}$.
\end{proposition}
\begin{proof}
If $\Phi_a \equiv 0$ then $0 = \Phi_a(y)_0 = \ip{a}{y}$ for all $y$, so
$\mathrm{pair}(a) = 0$ and $a = 0$ by Lemma~\ref{lem:coeff}.
\end{proof}

\begin{proposition}[Core bridge]\label{prop:core}
For every $a \in V$,
\[
\ker\ip{a}{\cdot} \text{ is cyclically covering}
\iff \Phi_a(V) \text{ contains no full-weight word}.
\]
\end{proposition}
\begin{proof}
($\Rightarrow$) Let $H = \ker\ip{a}{\cdot}$ be covering and $w = \Phi_a(x)$
arbitrary. Covering gives $k$ with $\ip{a}{\rot_k x} = 0$, i.e.\ $w_k =
\Phi_a(x)_k = 0$, so $w$ is not full-weight.

($\Leftarrow$) Let $\Phi_a(V)$ have no full-weight word and $x \in V$. Then
$\Phi_a(x)$ is not full-weight, so some $\Phi_a(x)_k = \ip{a}{\rot_k x} = 0$,
whence $\rot_k(x) \in H$. As $x$ was arbitrary, $H$ is covering.
\end{proof}

\begin{proposition}[Reversal lands in the code]\label{prop:rev}
Let $C$ be a cyclic code and $c \in C$. Then for every $x \in V$,
\[
\Phi_{\rev(c)}(x) = \sum_{j \in \Zn} x_j\, \rot_{-j}(c) \in C.
\]
\end{proposition}
\begin{proof}
Coordinate $k$ of the left side is $\sum_i c_{-i}\, x_{i+k}$; reindexing $i
\mapsto i+k$ yields $\sum_j x_j\, c_{k-j} = \sum_j x_j (\rot_{-j} c)_k$. Each
$\rot_{-j}(c) \in C$ by Lemma~\ref{lem:shiftinv}, and $C$ is closed under linear
combinations.
\end{proof}

\section{The main theorem}

\begin{theorem}[Bridge Theorem]\label{thm:main}
$h_q(n) = 0$ if and only if $\FF_q^n$ has the full-weight property. More
generally, for any field $K$ and $V = K^{\Zn}$, the only cyclically covering
subspace is $V$ itself if and only if every nonzero cyclic code in $V$ contains a
full-weight codeword.
\end{theorem}
\begin{proof}
($\Rightarrow$) Assume the only covering subspace is $V$. Let $C \neq \{0\}$ be
cyclic and suppose it has no full-weight word. Pick $c \in C \setminus \{0\}$ and
set $a = \rev(c) \neq 0$. By Proposition~\ref{prop:rev}, $\Phi_a(V) \subseteq C$,
so $\Phi_a(V)$ has no full-weight word; Proposition~\ref{prop:core} then makes
$\ker\ip{a}{\cdot}$ covering, forcing $\ker\ip{a}{\cdot} = V$, i.e.\
$\mathrm{pair}(a) = 0$ and $a = 0$ (Lemma~\ref{lem:coeff}), a contradiction.
Hence $C$ has a full-weight word.

($\Leftarrow$) Assume the full-weight property and let $U$ be covering with
$U \neq V$. By Lemma~\ref{lem:sep} take a nonzero $f$ vanishing on $U$ and put $a
= \coeff(f)$, so $\mathrm{pair}(a) = f \neq 0$ and $a \neq 0$. Then $U \subseteq
\ker\ip{a}{\cdot}$, which is covering by Lemma~\ref{lem:mono}, so
Proposition~\ref{prop:core} shows $\Phi_a(V)$ has no full-weight word. But
$\Phi_a(V)$ is a nonzero cyclic code (Propositions~\ref{prop:image},
\ref{prop:nontriv}), so by hypothesis it \emph{has} a full-weight word---a
contradiction. Hence $U = V$ and $h_q(n) = 0$.
\end{proof}

\begin{remark}[Role of the field hypothesis]
The proof uses only field structure (Lemmas~\ref{lem:sep} and~\ref{lem:coeff});
finiteness of $\FF_q$ is never invoked, so Theorem~\ref{thm:main} holds over
every field $K$.
\end{remark}

\begin{remark}[What the transform computes]
Combining Propositions~\ref{prop:rev} and~\ref{prop:nontriv}, the image
$\Phi_{\rev(c)}(V)$ is exactly the cyclic code generated by $c$, i.e.\ the span of
the rotations of $c$. Thus $\Phi$ surjects words onto single-generator cyclic
codes.
\end{remark}

\section{Worked example: binary length three}

Take $K = \FF_2$ and $n = 3$. The even-weight code
\[
C_{\mathrm{ev}} = \{x \in \FF_2^3 : x_0 + x_1 + x_2 = 0\} = \{000, 110, 101, 011\}
\]
is cyclic and nonzero, with word weights $0, 2, 2, 2$; the unique full-weight
candidate $111$ has coordinate sum $1$ and is absent. So the full-weight property
fails. By Theorem~\ref{thm:main}, $h_2(3) \neq 0$. The even-weight code itself is
\emph{not} covering (rotation preserves the coordinate sum, so $111$ never enters
it); the covering witness comes from the reversal construction. Taking $c =
(1,1,0)$ and $a = \rev(c) = (1,0,1)$, Remark~\ref{prop:rev} gives $\Phi_a(V) =
\langle c\rangle \subseteq C_{\mathrm{ev}}$, so Proposition~\ref{prop:core} makes
the hyperplane $\ker\ip{(1,0,1)}{\cdot} = \{x_0 + x_2 = 0\}$ cyclically covering
(for every $x$ some rotation has $x_k = x_{k+2}$). It has codimension $1$, and a
dimension count gives $h_2(3) = 1$. Generally, whenever $x^n - 1$ acquires a repeated
factor over $\FF_q$ (equivalently $\gcd(n,q) > 1$), degenerate codes appear,
code-richness fails, and $h_q(n) \geq 1$.

\section{Algorithms}

\begin{enumerate}
\item[(A)] \textbf{Hyperplane covering test.} Given $a \neq 0$, iterate over all
$x \in V$; the hyperplane is covering iff each $x$ has a rotation with
$\ip{a}{\rot_k x} = 0$. Complexity $O(q^n n^2)$.
\item[(B)] \textbf{Deciding $h_q(n)=0$.} Since every proper subspace lies in a
hyperplane and covering is monotone, $h_q(n) = 0$ iff no hyperplane
$\ker\ip{a}{\cdot}$ is covering. Enumerate directions $a$ and apply (A).
\item[(C)] \textbf{Deciding the full-weight property.} Enumerate cyclic codes as
divisors of $x^n - 1$ over $\FF_q$; the property holds iff each nonzero code has a
full-weight word. Comparing (B) and (C) confirms Theorem~\ref{thm:main}
numerically.
\end{enumerate}

\section{Applications and discussion}

Cyclic codes underlie Reed--Solomon, BCH, and CRC constructions; full-weight
codewords are their maximally dispersed members. The covering invariant $h_q(n)$
measures how constrained a subspace can be while still covering the ambient space
under the shift action. Theorem~\ref{thm:main} shows these two literatures compute
a single boundary phenomenon from opposite sides, and each concrete instance on
one side manufactures one on the other. The transform $\Phi_a$ is a
matched-filter / sliding-correlation operator, tying the result to signal
processing intuition.

\section{Future directions}

\begin{enumerate}
\item \textbf{Quantitative version.} Formalize $h_q(n)$ as an explicit natural
number and prove $h_q(n) = n - \max\{\dim C : C \text{ cyclic with no full-weight
codeword}\}$.
\item \textbf{Positivity criteria.} Prove $h_q(n) \geq 1$ whenever $\gcd(n,q) > 1$
(more generally, when $x^n - 1$ has a repeated factor), using the even-weight
code as witness.
\item \textbf{Known values.} Establish $h_2(3) = 1$ and the coprime cases $h_q(n)
= 0$.
\item \textbf{Reversal-free bridge.} Package $a \mapsto \langle a\rangle$ as an
explicit bijection between covering hyperplanes and nonzero cyclic codes without
full-weight words, via $\FF_q[x]/(x^n-1)$.
\item \textbf{Ring-theoretic refactor.} Recast cyclic codes as ideals of
$\FF_q[x]/(x^n-1)$ and the shift as multiplication by $x$, connecting to
BCH/Reed--Solomon theory.
\item \textbf{Covering-code connections.} Relate $h_q(n)$ to covering radii and to
normalized-covering-codimension lower bounds, toward asymptotic estimates.
\end{enumerate}

