from itertools import product
from typing import List, Sequence, Set, Tuple

Vec = Tuple[int, ...]

def all_vectors(p: int, n: int) -> List[Vec]:
    return [tuple(v) for v in product(range(p), repeat=n)]

def rot(x: Vec, k: int) -> Vec:
    n = len(x)
    return tuple(x[(i + k) % n] for i in range(n))

def rotations(x: Vec) -> List[Vec]:
    return [rot(x, k) for k in range(len(x))]

def rev(x: Vec) -> Vec:
    n = len(x)
    return tuple(x[(-i) % n] for i in range(n))

def pair(a: Vec, x: Vec, p: int) -> int:
    return sum(ai * xi for ai, xi in zip(a, x)) % p

def phi(a: Vec, x: Vec, p: int) -> Vec:
    n = len(x)
    return tuple(pair(a, rot(x, k), p) for k in range(n))

def is_full_weight(c: Vec) -> bool:
    return all(ci != 0 for ci in c)

def rref(rows: Sequence[Vec], p: int) -> Tuple[Vec, ...]:
    n = len(rows[0]) if rows else 0
    mat = [list(r) for r in rows]
    pr = 0
    for col in range(n):
        sel = next((r for r in range(pr, len(mat)) if mat[r][col] % p != 0), None)
        if sel is None:
            continue
        mat[pr], mat[sel] = mat[sel], mat[pr]
        inv = pow(mat[pr][col], p - 2, p)
        mat[pr] = [(v * inv) % p for v in mat[pr]]
        for r in range(len(mat)):
            if r != pr and mat[r][col] % p != 0:
                f = mat[r][col]
                mat[r] = [(a - f * b) % p for a, b in zip(mat[r], mat[pr])]
        pr += 1
        if pr == len(mat):
            break
    return tuple(sorted(tuple(row) for row in mat if any(v % p != 0 for v in row)))

def span_words(basis: Sequence[Vec], p: int) -> List[Vec]:
    if not basis:
        return [tuple()]
    n = len(basis[0])
    words: Set[Vec] = set()
    for coeffs in product(range(p), repeat=len(basis)):
        w = [0] * n
        for c, b in zip(coeffs, basis):
            for i in range(n):
                w[i] = (w[i] + c * b[i]) % p
        words.add(tuple(w))
    return list(words)
def covering_ker(a: Vec, p: int) -> bool:
    """Decide whether the hyperplane ker<a,.> is cyclically covering."""
    n = len(a)
    for x in all_vectors(p, n):
        if not any(pair(a, rot(x, k), p) == 0 for k in range(n)):
            return False
    return True
def h_zero(p: int, n: int) -> bool:
    """Decide h_q(n) = 0: no nonzero direction a yields a covering hyperplane."""
    zero = (0,) * n
    for a in all_vectors(p, n):
        if a == zero:
            continue
        if covering_ker(a, p):
            return False
    return True
def all_cyclic_codes(p: int, n: int) -> List[Tuple[Vec, ...]]:
    """All cyclic codes as canonical RREF bases (each is span of a generator's rotations)."""
    codes: Set[Tuple[Vec, ...]] = set()
    for c in all_vectors(p, n):
        codes.add(rref(rotations(c), p))
    return list(codes)

def code_has_full_weight(basis: Sequence[Vec], p: int) -> bool:
    return any(is_full_weight(w) for w in span_words(basis, p))

def full_weight_property(p: int, n: int) -> bool:
    """Decide whether every nonzero cyclic code has a full-weight codeword."""
    for basis in all_cyclic_codes(p, n):
        if basis and not code_has_full_weight(basis, p):
            return False
    return True

def demo_equivalence_table() -> None:
    header = "  q   n |   h_q(n)=0  full-weight   match"
    print(header)
    print("-" * len(header))
    for p, n in [(2,2),(2,3),(2,4),(2,5),(3,2),(3,3),(3,4),(5,2),(5,3)]:
        hz, fw = h_zero(p, n), full_weight_property(p, n)
        tag = "OK" if hz == fw else "FAIL"
        print(f"{p:>3} {n:>3} | {str(hz):>10} {str(fw):>12} {tag:>7}")

if __name__ == "__main__":
    demo_equivalence_table()

