    n = len(x)
    return tuple(x[(-i) % n] for i in range(n))

def pair(a: Vec, x: Vec, p: int) -> int:
    return sum(ai * xi for ai, xi in zip(a, x)) % p

def phi(a: Vec, x: Vec, p: int) -> Vec:
    n = len(x)
    return tuple(pair(a, rot(x, k), p) for k in range(n))

def is_full_weight(c: Vec) -> bool:
    return all(ci != 0 for ci in c)

def rref(rows: Sequence[Vec], p: int) -> Tuple[Vec, ...]:
    n = len(rows[0]) if rows else 0
    mat = [list(r) for r in rows]
    pr = 0
    for col in range(n):
        sel = next((r for r in range(pr, len(mat)) if mat[r][col] % p != 0), None)
        if sel is None:
            continue
        mat[pr], mat[sel] = mat[sel], mat[pr]
        inv = pow(mat[pr][col], p - 2, p)
        mat[pr] = [(v * inv) % p for v in mat[pr]]
        for r in range(len(mat)):
            if r != pr and mat[r][col] % p != 0:
                f = mat[r][col]
                mat[r] = [(a - f * b) % p for a, b in zip(mat[r], mat[pr])]
        pr += 1
        if pr == len(mat):
            break
    return tuple(sorted(tuple(row) for row in mat if any(v % p != 0 for v in row)))

def span_words(basis: Sequence[Vec], p: int) -> List[Vec]:
    if not basis:
        return [tuple()]
    n = len(basis[0])
    words: Set[Vec] = set()
    for coeffs in product(range(p), repeat=len(basis)):
        w = [0] * n
        for c, b in zip(coeffs, basis):
            for i in range(n):
                w[i] = (w[i] + c * b[i]) % p
        words.add(tuple(w))
    return list(words)
def covering_ker(a: Vec, p: int) -> bool:
    """Decide whether the hyperplane ker<a,.> is cyclically covering."""
    n = len(a)
    for x in all_vectors(p, n):
        if not any(pair(a, rot(x, k), p) == 0 for k in range(n)):
            return False
    return True

def code_has_full_weight(basis: Sequence[Vec], p: int) -> bool:
    return any(is_full_weight(w) for w in span_words(basis, p))

