    print("full-weight word in C_ev?", code_has_full_weight(even, p))
    print("ker<(1,1,1)> covering? (no; rotation fixes the sum)", covering_ker((1,1,1), p))
    print("ker<(1,0,1)>=rev(110) covering? (yes; the true witness)", covering_ker((1,0,1), p))
